theorem transportCost_eq_sum_pair {p q : Fin n → ℝ} {π : Fin n → Fin n → ℝ}
    (hπ : IsTransportPlan p q π) (U V : Fin n → ℝ) :
    transportCost (fun a b => U a + V b) π = (∑ a, U a * p a) + ∑ b, V b * q b

theorem plan_kr_pair_sum {p q : Fin n → ℝ} {π : Fin n → Fin n → ℝ}
    (hπ : IsTransportPlan p q π) (f : Fin n → ℝ) :
    (∑ a, ∑ b, π a b * (f a - f b)) = (∑ a, f a * p a) - ∑ b, f b * q b

theorem kr_pairValue_le_plan_cost {p q : Fin n → ℝ} {π : Fin n → Fin n → ℝ}
    (hπ : IsTransportPlan p q π) {f : Fin n → ℝ} (hf : IsOneLipschitz f) :
    (∑ a, f a * p a) - ∑ b, f b * q b ≤ transportCost (absCost n) π

theorem weighted_minimizer_set_convex (f : Fin n → ℝ → ℝ) (S : Set ℝ) (w : Fin n → ℝ)
    (hS : Convex ℝ S) (hconv : ∀ i, ConvexOn ℝ S (f i)) (hw : ∀ i, 0 ≤ w i) :
    Convex ℝ {x | x ∈ S ∧ ∀ y ∈ S, WeightedSum f w x ≤ WeightedSum f w y}

lemma Subgradient.add {f g : ℝ → ℝ} {x gf gg : ℝ}
    (hf : Subgradient f x gf) (hg : Subgradient g x gg) :
    Subgradient (fun y => f y + g y) x (gf + gg)

theorem subdiff_add_eq_of_tight {f g : ℝ → ℝ} {x gf : ℝ}
    (htight : ∀ y, f y = f x + gf * (y - x)) :
    Subdiff (fun y => f y + g y) x ⊆ Subdiff f x + Subdiff g x
